local mapper = mapper
local config = "l2tpipsecserver"

local l2tpipsecserver_global = {
  config = config,
  section = "global",
  options = { "enabled" }
}

local l2tpipsecserver_ipsec = {
  config = config,
  section = "ipsec_global",
  options = { "PSK" }
}


local l2tpipsecserver_l2tpuser = {
    config = config,
    type = "l2tp_user",
    options = { "name", "secret" }
}

mapper("uci_1to1").registerConfigMap(config)
mapper("uci_1to1").registerSimpleMap(l2tpipsecserver_global)
mapper("uci_1to1").registerSimpleMap(l2tpipsecserver_ipsec)
mapper("uci_1to1").registerMultiMap(l2tpipsecserver_l2tpuser)

